__NUXT_JSONP__("/anticorrupcion/eventos/la_participacion_ciudadana_es_indispensable_en_el_combate_a_la_corrupcion", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{post:{slug:"la_participacion_ciudadana_es_indispensable_en_el_combate_a_la_corrupcion",title:"La participación ciudadana es indispensable en el combate a la corrupción",date:"2022-12-06T19:37:06.287Z",img:"https:\u002F\u002Fucarecdn.com\u002F9c07cd7a-8073-451c-ba71-530cba2aeecc\u002F","img-alt":"Dalia Toledo Ethos",autor:"Ethos",category:"anticorrupcion",extracto:"En el marco del Día Internacional contra la Corrupción, Dalia Toledo participó en un foro organizado por el INAI, donde destacó la necesidad de impulsar la participación ciudadana en la lucha anticorrupción.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Dalia Toledo, directora de Finanzas Públicas y Anticorrupción de Ethos, participó en el panel “Promesas y obstáculos de la participación ciudadana y la inclusión de los grupos vulnerables en el combate a la corrupción”. Este evento se realizó en el marco del foro El futuro del Acceso a la Información en el combate a la corrupción, organizado por el Instituto Nacional de Transparencia y Acceso a la Información (INAI) en conmemoración del Día Internacional contra la Corrupción."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"En su intervención expresó que la indiferencia es uno de los principales retos a vencer para que la ciudadanía se involucre en el combate a la corrupción y se debe principalmente a la sensación de que el Sistema Nacional Anticorrupción no ha dado los resultados esperados y al desconocimiento sobre qué son los sistemas nacional y estatales anticorrupción, así como su funcionamiento. "}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Por otro lado, hizo referencia a los grupos en situación de vulnerabilidad como los pueblos indígenas, e indicó que es complejo involucrarlos en el combate a la corrupción por temas como el idioma y la accesibilidad; sin embargo, es necesario esforzarse para lograrlo y el acceso a la información con pertinencia cultural es fundamental."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"En el panel también participaron "},{type:b,tag:d,props:{href:"https:\u002F\u002Fmoritzlaw.osu.edu\u002Fmargaret-kwoka",rel:[e,f,g],target:h},children:[{type:a,value:"Margaret Kwoka"}]},{type:a,value:", profesora de Derecho de la Universidad de Ohio, becaria Fulbright, afiliada al Instituto de Investigación en Rendición de Cuentas y Combate a la Corrupción de la Universidad de Guadalajara; "},{type:b,tag:d,props:{href:"https:\u002F\u002Fhome.inai.org.mx\u002F?page_id=1740",rel:[e,f,g],target:h},children:[{type:a,value:"Josefina Román Vergara"}]},{type:a,value:", comisionada del INAI y "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.linkedin.com\u002Fin\u002Fcarlos-cort%C3%A9s-zea-8b872086\u002F?originalSubdomain=mx",rel:[e,f,g],target:h},children:[{type:a,value:"Carlos Cortés Zea"}]},{type:a,value:", oficial nacional de Gobernanza Efectiva y Democracia del PNUD México. Se contó con la moderación de "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.linkedin.com\u002Fin\u002Fileana-hidalgo-rioja-36719a150\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Ileana Hidalgo Rioja"}]},{type:a,value:", de la  Secretaría de Acceso a la Información del INAI."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Si te lo perdiste, puedes verlo aquí: "},{type:b,tag:d,props:{href:j,rel:[e,f,g],target:h},children:[{type:a,value:j}]}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fla_participacion_ciudadana_es_indispensable_en_el_combate_a_la_corrupcion",extension:".md",createdAt:"2023-06-19T05:12:00.327Z",updatedAt:"2023-03-01T16:25:15.994Z"}}],fetch:{},mutations:[]}}("text","element","p","a","nofollow","noopener","noreferrer","_blank","\n","https:\u002F\u002Fbit.ly\u002F3VVbRj9")));